const siteUrl = config.gympilotUrl;
const promo = config.promoCode;
const imageUrl = config.marketingImageUrl;

const copyCatalog = {
  fr_weight_loss: `🔥 Tu veux te débarrasser de tes kilos en trop durablement sans régime toxique ni effet yo-yo ? Découvre GymPilot ! 🚀\n\nLa plupart des personnes en surpoids abandonnent parce qu'elles sont perdues entre les régimes stricts et les entraînements inadaptés.\n\nGymPilot (https://gympilot.tn) est votre copilote intelligent boosté par l'IA pour reprendre le contrôle total de votre corps :\n\n✨ CE QUE GYMPILOT FAIT POUR VOTRE TRANSFORMATION :\n🥗 Calculateur de déficit calorique & macronutriments sur-mesure (sans vous affamer)\n🤖 Analyse IA de votre silhouette et suivi précis de la perte de graisse\n🏃 Entraînements progressifs adaptés aux débutants comme aux confirmés\n📊 Suivi visuel des mensurations et de vos victoires quotidiennes\n\n🛡️ GARANTIE 14 JOURS 100% SATISFAIT OU REMBOURSÉ !\nTestez l'application sans aucun risque pendant 14 jours. Remboursement intégral si non satisfait.\n\n🎁 Code promo spécial membres du groupe : ${promo} (-20% sur l'abonnement)\n👉 Commencez votre transformation dès aujourd'hui : ${siteUrl}\n\n#PerteDePoids #RemiseEnForme #AntiObésité #TransformationPhysique #Santé #FitnessFrance #GymPilot`,

  fr_gym: `⚡ Arrête de stagner à la salle ! Passe au niveau supérieur avec GymPilot 🚀\n\nPour construire du muscle durablement, le suivi de la surcharge progressive est la clé numéro 1.\n\nGymPilot (https://gympilot.tn) :\n📊 Suivi ultra-rapide de la surcharge progressive et de vos records personnels (PRs)\n🤖 Analyse IA de votre physique avec directives d'hypertrophie personnalisées\n🥗 Calculateur précis pour prise de masse propre ou sèche\n\n🛡️ GARANTIE 14 JOURS 100% SATISFAIT OU REMBOURSÉ !\n🎁 Code promo exclusif : ${promo}\n👉 Testez dès maintenant : ${siteUrl}\n\n#Musculation #GoMuscu #FitnessFrance #Hypertrophie #GymPilot`
};

const queue = config.targetGroups.map(group => {
  let copyKey = `${group.language}_${group.niche}`;
  if (!copyCatalog[copyKey]) {
    copyKey = group.niche === 'gym' ? 'fr_gym' : 'fr_weight_loss';
  }

  return {
    groupId: group.groupId,
    groupName: group.groupName,
    groupUrl: group.groupUrl || `https://www.facebook.com/groups/${group.groupId}`,
    country: group.country,
    language: group.language,
    niche: group.niche,
    imageUrl: imageUrl,
    caption: copyCatalog[copyKey],
    accessToken: config.facebookPageAccessToken,
    shareUrl: siteUrl
  };
});

return queue.map(item => ({ json: item }));

